// port
interface UserRepository {
    fun findByLogin(login: String): User?
}

// adapter (raw SQL)
class PostgresUserRepository(private val ds: DataSource) : UserRepository {
    override fun findByLogin(login: String): User? =
        ds.connection.use { c ->
            c.prepareStatement("SELECT id, login, password_hash FROM users WHERE login = ?").use { ps ->
                ps.setString(1, login)
                ps.executeQuery().use { rs ->
                    if (rs.next()) User(rs.getLong("id"), rs.getString("login"), rs.getString("password_hash"))
                    else null
                }
            }
        }
}

// domain service
class AuthService(private val repo: UserRepository) {
    fun login(login: String, password: String): String? {
        val u = repo.findByLogin(login) ?: return null
        if (!BCrypt.verifyer().verify(password.toCharArray(), u.passwordHash).verified) return null
        return issueToken(u) // JWT или серверная сессия
    }
}

// Ktor route
fun Route.auth(auth: AuthService) {
    post("/login") {
        val body = call.receive<LoginRequest>()
        val token = auth.login(body.login, body.password)
        if (token == null) call.respond(HttpStatusCode.Unauthorized)
        else call.respond(mapOf("token" to token))
    }
}
