// AuthService.java
@Service
public class AuthService {

    private final UserRepository users;
    private final PasswordEncoder encoder;
    private final JwtService jwt;

    public AuthService(UserRepository users, PasswordEncoder encoder, JwtService jwt) {
        this.users = users;
        this.encoder = encoder;
        this.jwt = jwt;
    }

    public TokenResponse login(LoginRequest req) {
        User user = users.findByEmail(req.email())
                .orElseThrow(() -> new BadCredentialsException("bad creditentials"));

        if (!encoder.matches(req.password(), user.getPasswordHash())) {
            throw new BadCredentialsException("bad credentials");
        }

        String access = jwt.issueAccess(user);
        String refresh = jwt.issueRefresh(user);
        return new TokenResponse(access, refresh);
    }

    public TokenResponse refresh(String refreshToken) {
        var claims = jwt.parse(refreshToken);
        User user = users.findById(claims.subject())
                .orElseThrow(() -> new BadCredentialsException("user not found"));
        return new TokenResponse(jwt.issueAccess(user), jwt.issueRefresh(user));
    }
}
```

