    override fun findByLogin(login: String) = ds.connection.use { c ->
        c.prepareStatement("SELECT id, login, password_hash FROM users WHERE login = ?").use { ps ->
            ps.setString(1, login)
            ps.executeQuery().use { rs ->
                if (rs.next()) UserRecord(rs.getLong("id"), rs.getString("login"), rs.getString("password_hash")) else null
            }
        }
    }
}

